	bool same = false;

	switch (size) {
	case sizeof(u8):
		same = ((*(u8 *)valp) & (*(u8 *)maskp)) ==
		       ((*(u8 *)matchvalp) & (*(u8 *)matchmaskp));
		break;
	case sizeof(u16):
		same = ((*(u16 *)valp) & (*(u16 *)maskp)) ==
		       ((*(u16 *)matchvalp) & (*(u16 *)matchmaskp));
		break;
	case sizeof(u32):
		same = ((*(u32 *)valp) & (*(u32 *)maskp)) ==
		       ((*(u32 *)matchvalp) & (*(u32 *)matchmaskp));
		break;
	}

	return same;


